#include <iostream>
#include <string>
#include <vector>
#include <curl/curl.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <fstream>
#include <sstream>
#include <mutex>
#include <thread>
#include <chrono>

struct IndexDocument {
    std::string url;
    std::string content;
    std::string resolved_ip;
    bool is_internal;
};

class NetworkPolicy {
public:
    static bool is_private_ip(const std::string& ip) {
        if (ip.find("127.") == 0) return true;
        if (ip.find("10.") == 0) return true;
        if (ip.find("192.168.") == 0) return true;
        if (ip.find("172.") == 0) {
            int second_octet = std::stoi(ip.substr(4, ip.find('.', 4) - 4));
            if (second_octet >= 16 && second_octet <= 31) return true;
        }
        if (ip == "169.254.169.254") return true;
        return false;
    }

    static std::string resolve_hostname(const std::string& hostname) {
        struct addrinfo hints{}, *res;
        hints.ai_family = AF_INET;
        hints.ai_socktype = SOCK_STREAM;
        if (getaddrinfo(hostname.c_str(), nullptr, &hints, &res) != 0) {
            return "";
        }
        char ip[INET_ADDRSTRLEN];
        struct sockaddr_in* addr = (struct sockaddr_in*)res->ai_addr;
        inet_ntop(AF_INET, &addr->sin_addr, ip, sizeof(ip));
        freeaddrinfo(res);
        return std::string(ip);
    }
};

class DocumentFetcher {
private:
    std::mutex fetch_mutex_;

    static size_t write_callback(void* contents, size_t size, size_t nmemb, std::string* output) {
        size_t total = size * nmemb;
        output->append((char*)contents, total);
        return total;
    }

public:
    bool validate_and_fetch(IndexDocument& doc) {
        // Phase 1: DNS resolution and policy check
        std::string hostname = extract_hostname(doc.url);
        if (hostname.empty()) return false;

        std::string ip = NetworkPolicy::resolve_hostname(hostname);
        if (ip.empty()) return false;

        doc.resolved_ip = ip;
        doc.is_internal = NetworkPolicy::is_private_ip(ip);

        if (doc.is_internal) {
            std::cerr << "[BLOCKED] Internal IP detected: " << ip << std::endl;
            return false;
        }

        // Phase 2: Fetch content (uses system resolver again)
        std::lock_guard<std::mutex> lock(fetch_mutex_);
        return fetch_content(doc);
    }

private:
    std::string extract_hostname(const std::string& url) {
        size_t start = url.find("://");
        if (start == std::string::npos) return "";
        start += 3;
        size_t end = url.find('/', start);
        if (end == std::string::npos) end = url.length();
        std::string host_port = url.substr(start, end - start);
        size_t colon = host_port.find(':');
        if (colon != std::string::npos) host_port = host_port.substr(0, colon);
        return host_port;
    }

    bool fetch_content(IndexDocument& doc) {
        CURL* curl = curl_easy_init();
        if (!curl) return false;

        std::string response;
        curl_easy_setopt(curl, CURLOPT_URL, doc.url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
        curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
        curl_easy_setopt(curl, CURLOPT_MAXREDIRS, 3L);

        CURLcode res = curl_easy_perform(curl);
        curl_easy_cleanup(curl);

        if (res == CURLE_OK) {
            doc.content = response;
            return true;
        }
        return false;
    }
};

class SearchIndexer {
private:
    DocumentFetcher fetcher_;
    std::vector<IndexDocument> index_;
    std::mutex index_mutex_;

public:
    bool process_upload(const std::string& manifest_path) {
        std::ifstream file(manifest_path);
        if (!file.is_open()) return false;

        std::string line;
        std::vector<std::string> urls;
        while (std::getline(file, line)) {
            if (!line.empty() && line.find("http") == 0) {
                urls.push_back(line);
            }
        }

        for (const auto& url : urls) {
            IndexDocument doc;
            doc.url = url;

            if (fetcher_.validate_and_fetch(doc)) {
                std::lock_guard<std::mutex> lock(index_mutex_);
                index_.push_back(std::move(doc));
                std::cout << "[INDEXED] " << doc.url << " (" << doc.resolved_ip << ")" << std::endl;
            }
        }
        return true;
    }

    size_t index_size() const { return index_.size(); }
};

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <manifest_file>" << std::endl;
        return 1;
    }

    curl_global_init(CURL_GLOBAL_DEFAULT);
    SearchIndexer indexer;
    indexer.process_upload(argv[1]);
    std::cout << "Indexed " << indexer.index_size() << " documents." << std::endl;
    curl_global_cleanup();
    return 0;
}
